    const start=(job,w,path)=>{job.worker=w.id;job.assignedBy='AUTO';job.assignedAt=stamp;job.cooldownMs=0;job.blocked=null;w.job=job.id;w.workerReason=null;if(path){job.state='ASSIGNED';w.walk={path,next:1,job:job.id};}else{job.state='IN_PROGRESS';job.startedAt=stamp;}this.repo.save(job);this.repo.save(w);free=free.filter(x=>x.id!==w.id);};
