  routineVerbs(w,board,liveKeys){return SKILLS.filter(s=>s.routine&&skillOn(w,s.code)).flatMap(s=>s.vocabulary.map(v=>({verb:v,category:s.code,priority:s.priority,done:board.marks['ROUTINE:'+v]??''}))).filter(x=>!liveKeys.has('ROUTINE:'+x.verb)).sort((a,b)=>a.done.localeCompare(b.done)||a.priority-b.priority);},
  routineJob(yard,v,target,stamp){const d=(this.jobsConfig().stepMs??700)*(4+(v.verb.length%5));return this.repo.add('job',{yard:yard.id,key:'ROUTINE:'+v.verb,origin:'ROUTINE',priority:v.priority,category:v.category,hazard:false,title:v.verb,detail:'Routine work between jobs (demo timer)',subject:null,effect:'RECORD',badge:'RECORDED',params:{},target,durationMs:d,remainingMs:d,state:'OPEN',worker:null,assignedBy:null,blocked:null,reason:null,cooldownMs:0,failures:0,result:null,actor:'engine:'+yard.id,createdAt:stamp,startedAt:null,completedAt:null});},
  spotClear(p,yard,obstacles){const r={x:p.x,y:p.y,w:500,h:500};return fitsPolygon(r,yard.points)&&!(obstacles??this.jobObstacles(yard)).some(o=>overlap(r,o));},
  // A stillage can be set down where a worker stands (placement does not treat crew as obstacles); such a worker is moved to clear ground.
